// 1. Le navigateur demande le certificat du serveur
// 2. Le certificat est vérifié auprès d'une autorité de certification (CA)
// 3. Client et serveur s'accordent sur une clé de session partagée
// 4. Toutes les données suivantes sont chiffrées avec cette clé
fetch('https://api.example.com/login', { method: 'POST', body: JSON.stringify(credentials) });
// -> le mot de passe transite chiffré, illisible en cas d'interception
// 5. Si le certificat n'est pas reconnu (auto-signé, expiré), le navigateur bloque la connexion par défaut
fetch('https://self-signed.example.com/data').catch(err => console.error('Échec TLS :', err.message));

const socket = new WebSocket('wss://chat.example.com');

socket.onopen = () => socket.send('Bonjour depuis le client !');

socket.onmessage = (event) => {
  console.log('Message reçu :', event.data);
};

socket.onclose = () => console.log('Connexion fermée');
